// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address nonOwner = address(0x123);
        vm.deal(nonOwner, 1 ether);
        uint256 balanceBefore = address(c).balance;
        vm.prank(nonOwner);
        bool ok;
        try c.sendMoney(nonOwner, 1 ether, "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == (address(c).balance == balanceBefore + 1 ether));
    }
}
